import assert from 'node:assert/strict';
import {readFileSync, writeFileSync} from 'node:fs';
const [from, to] = process.argv.slice(2);
const source = readFileSync(from, 'utf8').replaceAll('\r\n', '\n');
const name = '_M0MP210JingLan0v03stn10PlanBranch7compile';
const begin = source.indexOf('function ' + name + '(');
const end = source.indexOf('\nfunction ', begin + 1);
assert(begin >= 0 && end > begin);
let branch = source.slice(begin, end);
const stage = (line, extra) => {
  assert(line.test(branch), 'No match for ' + line);
  branch = branch.replace(line, '$1' + extra + '\n$&');
};
const sharedSuffix = /^( +)const before_suffix = /m;
stage(sharedSuffix.test(branch) ? sharedSuffix : /^( +)const id = `order/m,
  'orderProbe.children++; const started = performance.now();');
stage(/^( +)if \(.*self\.rule_ids, id\)\) \{/m,
  'orderProbe.idMs += performance.now() - started; const scanStarted = performance.now();');
const firstLookup = /^( +)const [^\n]+_M0MPC13int3Int18to__string_2einner\(_before, 10\);$/m;
const savedName = /^( +)let finish_name;$/m;
stage(savedName.test(branch) ? savedName : firstLookup,
  'orderProbe.scanMs += performance.now() - scanStarted; const edgesStarted = performance.now();');
stage(/^( +)const arcs = .*Array4copy/m,
  'orderProbe.endpointsMs += performance.now() - edgesStarted; const copyStarted = performance.now();');
stage(/^( +)return new .*2Ok\(\{ _0: arcs, _1: ids/m,
  'orderProbe.copyMs += performance.now() - copyStarted;');
branch = branch.replace(/_M0MPC13int3Int18to__string_2einner\((_before|_after), 10\)/g,
  '(orderProbe.conversions++, $&)').replace(/_M0FP210JingLan0v03stn12lookup__name\(/g,
  'orderLookup(');
const header = `const orderProbe = {children:0, conversions:0, lookups:0, idMs:0, scanMs:0, endpointsMs:0, copyMs:0};
const orderLookup = (...args) => { orderProbe.lookups++; return _M0FP210JingLan0v03stn12lookup__name(...args); };
process.once('exit', () => console.error(JSON.stringify(orderProbe)));\n`;
writeFileSync(to, header + source.slice(0, begin) + branch + source.slice(end));

names.patch:
diff --git a/published.mbt b/names.mbt
index 9d927c1..310ea00 100644
--- a/published.mbt
+++ b/names.mbt
@@ -266,12 +266,24 @@ fn PlanBranch::compile(
       "limit_exceeded", "require 1..64 timepoints and at most 512 constraints",
     )
   }
-  let id = "order" + before.to_string() + "_" + after.to_string()
+  let before_suffix = before.to_string()
+  let after_suffix = after.to_string()
+  let id = "order" + before_suffix + "_" + after_suffix
   if self.rule_ids.contains(id) {
     raise StnError("invalid_input", "invalid or duplicate constraint id")
   }
-  let finish = lookup_name(index, point(before.to_string(), true))
-  let start = lookup_name(index, point(after.to_string(), false))
+  let finish_name = if before < MAX_PLANNING_TASKS {
+    task_rule_names[before].finish
+  } else {
+    point(before_suffix, true)
+  }
+  let finish = lookup_name(index, finish_name)
+  let start_name = if after < MAX_PLANNING_TASKS {
+    task_rule_names[after].start
+  } else {
+    point(after_suffix, false)
+  }
+  let start = lookup_name(index, start_name)
   let arcs = self.arcs.copy()
   // finish(before) <= start(after) is a zero-weight lower-bound arc.
   arcs.push({ source: start, target: finish, bound: 0L, })

position.patch:
diff --git a/published.mbt b/position.mbt
index 9d927c1..7a5fd17 100644
--- a/published.mbt
+++ b/position.mbt
@@ -251,10 +251,26 @@ priv struct PlanBranch {
   order : (Int32, Int32)?
 }

+///|
+fn order_timepoint_index(
+  names : Array[String],
+  index : Map[String, Int32],
+  position : Int32,
+  name : String,
+) -> Int32 raise StnError {
+  // Root validation makes names unique. A caller can edit or move a name.
+  if names[position] == name {
+    position
+  } else {
+    lookup_name(index, name)
+  }
+}
+
 ///|
 fn PlanBranch::compile(
   self : PlanBranch,
   index : Map[String, Int32],
+  names : Array[String],
 ) -> (Array[TemporalArc], Array[String]) raise StnError {
   guard self.order is Some((before, after)) else {
     return (self.arcs, self.rule_ids)
@@ -266,12 +282,16 @@ fn PlanBranch::compile(
       "limit_exceeded", "require 1..64 timepoints and at most 512 constraints",
     )
   }
-  let id = "order" + before.to_string() + "_" + after.to_string()
+  let before_suffix = before.to_string()
+  let after_suffix = after.to_string()
+  let id = "order" + before_suffix + "_" + after_suffix
   if self.rule_ids.contains(id) {
     raise StnError("invalid_input", "invalid or duplicate constraint id")
   }
-  let finish = lookup_name(index, point(before.to_string(), true))
-  let start = lookup_name(index, point(after.to_string(), false))
+  let finish_name = point(before_suffix, true)
+  let finish = order_timepoint_index(names, index, 2 + 2 * before, finish_name)
+  let start_name = point(after_suffix, false)
+  let start = order_timepoint_index(names, index, 1 + 2 * after, start_name)
   let arcs = self.arcs.copy()
   // finish(before) <= start(after) is a zero-weight lower-bound arc.
   arcs.push({ source: start, target: finish, bound: 0L, })
@@ -330,7 +350,7 @@ pub fn plan(
         "limit_exceeded", "planning node budget exhausted; no feasibility conclusion",
       )
     }
-    let (arcs, rule_ids) = stack.pop().unwrap().compile(index)
+    let (arcs, rule_ids) = stack.pop().unwrap().compile(index, p.names)
     let e = arcs.length()
     // Keep the 0.2.0 full-solve charge while computing only a feasibility witness.
     let work = n * n * n + n * e + e + 2 * n

